**三、在这题里怎么用（走一遍样例第二组）。** $n = 2$、$x = 3$：1 号楼两层 $a = (4,4)$、$b = (5,5)$，2 号楼两层 $a = (2,20)$、$b = (4,0)$。2 号楼第二层净亏 20，压完只剩一块 $(2,2)$；1 号楼压成两块 $(4,1)$、$(4,1)$。归并后 $T$ 依次是 $(2,2)$、$(4,1)$、$(4,1)$。把 1 号楼当目标：先吃第一块（需求 $2 \le 3$），钱变 5，再逐层盖自己的楼 $5 \to 6 \to 7$，高度 2。把 2 号楼当目标：先盖自己第一层（$3 \to 5$），再去吃那两个 $(4,1)$ 变成 7，仍买不起第二层的 20，高度只有 1。取高者：高度 2 来自 1 号楼，与样例一致。

### 思路

1. 选定目标楼 $i$ 之后，其余楼都只是赚钱工具，用上面的块压缩把它们的链变成 $(\mathrm{req}, \mathrm{gain} > 0)$ 的块；目标楼自己的块不参与赚钱。
2. 用优先队列把各楼的块按「队首 $\mathrm{req}$ 最小者先出」归并成 $T$，并记下每栋楼的块落在 $T$ 的哪些位置（`bpos[i]`）。这个顺序与资金无关，预处理一次即可。
3. 在 $T$ 上建倍增表（`reqv[k][j]`、`gainv[k][j]`、`jmp[k][j]`），设总块数为 $K$。
4. 对每个目标楼 $i$ 单独模拟，每轮做两件事：
   - **吃帮手**：从当前位置沿 $T$ 用倍增尽量往后吃，但被 $i$ 自己的下一个块挡住（最多吃到它前面一格）；碰到自己的块就跳过，继续吃它后面的。
   - **盖自己的楼**：钱够第 $h$ 层的 $a_{i,h}$ 就盖，金额加上 $b_{i,h} - a_{i,h}$、高度加一；钱不够或已盖满 $m_i$ 层就结束这次模拟。
   自己的块只能跳过、不能当整块吃掉：题目要数的是层数，自己每盖一层都计入高度，逐层判钱比整块更细，还能利用层与层之间的进账。
5. 所有目标楼取高度最大者，高度相同时取编号最小的（判断写成严格大于才更新）。

### 参考代码

```cpp
// CF 2257E Busy Beaver
// 思路：
//  1) 每个建筑是一条「链」。把链压缩成若干块 (req, gain)，块内任意真前缀收益 <= 0、整块收益 > 0，
//     req = 从头做完这一整块在任何时刻所需的最低资金，gain = 净收益。
//     压缩：栈；每来一层，若栈顶块收益 <= 0 就把它并进来（req = max(req1, req2 - gain1)）。
//     末尾收益 <= 0 的块直接丢掉（它的任何前缀也不赚，永不值得做）。
//  2) 「只做能负担得起的块」这个过程，等价于：把所有链按「队首块 req 最小者先出」归并成一个固定序列 T，
//     然后从头沿 T 走、能负担就吃、吃不下去就停。归并顺序与资金无关（可用小根堆预处理）。
//  3) 在 T 上建倍增表：从位置 j 连走 2^k 个块看作一跳，记录
//     需求 req[k][j]（在 j 处至少要有多少钱才走得过）与总收益 gain[k][j]。
//  4) 对每个目标建筑 i 单独模拟（其余建筑的块就是「帮手」）：
//     反复「沿 T 把帮手吃到吃不动」→「建 i 的下一层」。
//     走到 i 自己的块时直接跳过（i 的楼层要逐层建，比整块更细，能利用层间收益）；
//     倍增 + 段指针保证每次模拟总代价 O((m_i + 高度) log)。
// 复杂度：O((Σm) log(Σm))。
#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int tc;
    cin >> tc;
    while (tc--) {
        int n;
        ll x;
        cin >> n >> x;
        vector<vector<ll>> A(n), B(n);
        for (int i = 0; i < n; i++) {
            int m;
            cin >> m;
            A[i].assign(m, 0);
            B[i].assign(m, 0);
            for (int j = 0; j < m; j++) cin >> A[i][j];
            for (int j = 0; j < m; j++) cin >> B[i][j];
        }
        // ---- 1) 每条链压缩成块 (req, gain)，gain > 0 ----
        vector<vector<pair<ll, ll>>> blk(n);
        for (int i = 0; i < n; i++) {
            vector<pair<ll, ll>> st;
            for (size_t j = 0; j < A[i].size(); j++) {
                ll req = A[i][j], gain = B[i][j] - A[i][j];
                while (!st.empty() && st.back().second <= 0) {
                    ll r1 = st.back().first, g1 = st.back().second;
                    st.pop_back();
                    req = max(r1, req - g1);  // 先做完旧块再做新块
                    gain = g1 + gain;
                }
                st.push_back(make_pair(req, gain));
            }
            while (!st.empty() && st.back().second <= 0) st.pop_back();
            blk[i] = st;
        }
        // ---- 2) 归并成序列 T（队首 req 最小者先出）----
        vector<ll> Treq(1, 0), Tgain(1, 0);  // 1-indexed，位置 1..K
        vector<vector<int>> bpos(n);         // 每个建筑的块在 T 中的位置（递增）
        {
            typedef pair<pair<ll, int>, int> Item;  // ((req, 建筑), 块下标)
            priority_queue<Item, vector<Item>, greater<Item>> pq;
            for (int i = 0; i < n; i++)
                if (!blk[i].empty()) pq.push(make_pair(make_pair(blk[i][0].first, i), 0));
            while (!pq.empty()) {
                Item cur = pq.top();
                pq.pop();
                ll r = cur.first.first;
                int i = cur.first.second, k = cur.second;
                Treq.push_back(r);
                Tgain.push_back(blk[i][k].second);
                bpos[i].push_back((int)Treq.size() - 1);
                if (k + 1 < (int)blk[i].size())
                    pq.push(make_pair(make_pair(blk[i][k + 1].first, i), k + 1));
            }
        }
        int K = (int)Treq.size() - 1;
        // ---- 3) T 上的倍增表 ----
        int LOG = 1;
        while ((1 << LOG) <= K + 1) LOG++;
        vector<vector<int>> jmp(LOG, vector<int>(K + 1, K));
        vector<vector<ll>> reqv(LOG, vector<ll>(K + 1, 0));
        vector<vector<ll>> gainv(LOG, vector<ll>(K + 1, 0));
        for (int j = 0; j <= K; j++) {
            jmp[0][j] = (j < K ? j + 1 : K);
            if (j < K) {
                reqv[0][j] = Treq[j + 1];
                gainv[0][j] = Tgain[j + 1];
            }
        }
        for (int k = 1; k < LOG; k++) {
            for (int j = 0; j <= K; j++) {
                if (j + (1 << k) > K) {  // 这一跳越界，不会被用到
                    jmp[k][j] = K;
                    reqv[k][j] = 0;
                    gainv[k][j] = 0;
                    continue;
                }
                int mid = jmp[k - 1][j];
                jmp[k][j] = jmp[k - 1][mid];
                gainv[k][j] = gainv[k - 1][j] + gainv[k - 1][mid];
                reqv[k][j] = max(reqv[k - 1][j], reqv[k - 1][mid] - gainv[k - 1][j]);
            }
        }
        // ---- 4) 对每个建筑模拟 ----
        ll bestH = -1;
        int bestI = -1;
        for (int i = 0; i < n; i++) {
            int m = (int)A[i].size();
            ll money = x;
            int h = 0;
            int pos = 0;    // T 中已处理到位置 pos
            size_t pi = 0;  // bpos[i] 的指针
            while (true) {
                // 沿 T 把帮手块吃到吃不动（跳过建筑 i 自己的块）
                while (true) {
                    while (pi < bpos[i].size() && bpos[i][pi] <= pos) pi++;
                    int cap = (pi < bpos[i].size()) ? bpos[i][pi] - 1 : K;
                    if (cap > pos) {
                        for (int k = LOG - 1; k >= 0; k--) {
                            int nj = pos + (1 << k);
                            if (nj <= cap && money >= reqv[k][pos]) {
                                money += gainv[k][pos];
                                pos = nj;
                            }
                        }
                    }
                    if (pos < cap) break;  // 卡住，吃不动了
                    if (cap == K) break;   // 后面没有帮手块了
                    pos = cap + 1;         // 跳过建筑 i 的一个块
                }
                // 建建筑 i 的下一层
                if (h == m) break;
                if (money < A[i][h]) break;
                money += B[i][h] - A[i][h];
                h++;
            }
            if (h > bestH) {
                bestH = h;
                bestI = i + 1;
            }
        }
        cout << bestH << ' ' << bestI << '\n';
    }
    return 0;
}
```

### 复杂度

块压缩 $O(\sum m)$，归并 $O(K \log n)$，倍增表 $O(K \log K)$。每个目标楼 $i$ 的模拟是 $O((m_i + \text{自己的块数}) \log K)$：每轮要么盖一层、要么跳过自己的一个块、要么卡住结束，位置与层数都只增不减。总计 $O(\sum m \log \sum m)$，空间 $O(\sum m \log \sum m)$。实测三组极限：$n = 10^5$、每建筑 2 层（$\sum m = 2 \times 10^5$）0.377 s；单建筑 $m = 2 \times 10^5$、$x = 10^{18}$ 0.110 s；$t = 3 \times 10^4$ 组 0.089 s。

### 易错点

1. 合并公式别写反：$\mathrm{req} = \max(\mathrm{req}_1, \mathrm{req}_2 - \mathrm{gain}_1)$，第二块的需求要**减去**第一块的收益；写成加法会低估需求，模拟时吃下做不完的块。
2. 扫完一条链必须把栈顶残留的 $\mathrm{gain} \le 0$ 的块弹掉，否则「买得起就吃」会吃进净亏的块。
3. 目标楼自己的块在扫 $T$ 时要跳过、自己的楼层要逐层盖；把自己的块当帮手整块吃掉，等于少算了高度、多算了钱。
4. 倍增表里越界的那一跳（$j + 2^k > K$）要置成不可用，模拟里还得再判一次落点有没有越过这一轮能吃到的上限，否则会越过自己的块去提前领后面的收益。
5. 资金与累计收益都很大（$x$ 到 $10^{18}$、$\sum m_i$ 到 $2 \times 10^5$、每层进账到 $10^9$），一律用 `long long`；`LOG` 要按 $K+1$ 取够（代码用 `while ((1 << LOG) <= K + 1) LOG++;`）。

