## F2. Beaver's Jumping Track (Hard Version)

### 题意

与 F1 完全相同，只有约束不同：$1 \le x \le 10$（F1 是 $x \le 5$），时限 3 秒（F1 是 2 秒）；$n \le 10^6$、$q \le 10^4$、$d_i \le 10^7$、$s_i \le 10^5$ 都一样。

### 思路

算法与 F1 一模一样，$x$ 从 5 变 10 只是窗口向量变长、矩阵从 $5 \times 5$ 变成 $10 \times 10$，分块与线段树的结构不变，所以推导见 F1，这里只说清 $x$ 变大带来的变化。本场两人的参考代码逐字节相同（F1 用的 `MAXK` 已经是 10，直接覆盖 F2 的范围）。$x = 10$ 时一次矩阵乘法从 $5^3 = 125$ 次基本运算涨到 $10^3 = 1000$ 次，这才是块大小取 64、把线段树压到 14 层的原因。

### 参考代码

```cpp
// F1. Beaver's Jumping Track (Easy Version)
// n 个平台，第 i 个长 d_i 格、内部跳跃罚分 s_i；每次向前跳 <= x 格，
// 起跳与落点在同一平台内才罚 s_i。多次单点修改 + 询问「从平台 l 的第一格
// 走到平台 r 的最后一格」的最小罚分。
//
// 做法：把「最近 x 格的 dp 值」当作状态向量（x <= 10），平台就是一次
// min-plus 线性变换（x×x 矩阵）。状态向量按块（每 B 个平台一块）压缩，
// 块上建线段树；块内用 O(x) 的闭式递推把 x 个基向量推过去得到块矩阵。
#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

static const ll INF = (ll)4e18;      // 无穷大（饱和加不会溢出）
static const int MAXK = 10;          // x 的上限
static const int BLKSZ = 64;         // 每块的平台数

static int X;                        // 最大跳跃长度（运行时读入）

// 饱和加法：只要有一个是无穷就返回无穷，避免溢出
static inline ll sat(ll a, ll b) {
    if (a >= INF / 2 || b >= INF / 2) return INF;
    return a + b;
}

// ---------------------------------------------------------------
// 单个平台的转移：把一个窗口向量推过平台
// 约定：w[j] = f[L - x + j]（平台起点前 x 个格子，j = 0..x-1），
//       u[j] = f[R - x + 1 + j]（平台末尾 x 个格子）。
// 平台内第 j 格（1-based，j = 1..D）的代价
//   g_j = min( 从窗口里能直接免费跳过来的, s + 前 x 格里的最小值 )
// 前 x 格之后进入「稳态」：a_t = g_{x+t}，满足 a_t = a_{t-x} + s。
// ---------------------------------------------------------------
static void applyPlatform(ll D, ll s, const ll *w, ll *u) {
    const int x = X;
    ll q[MAXK + 2], p[MAXK + 2];     // q[j] = min(w[j-1..x-1])，p[j] = min(w[0..j-1])
    q[x + 1] = INF;
    for (int j = x; j >= 1; --j) q[j] = min(q[j + 1], w[j - 1]);
    p[0] = INF;
    for (int j = 1; j <= x; ++j) p[j] = min(p[j - 1], w[j - 1]);

    ll g[MAXK + 2], a[MAXK + 2];
    int gm = (int)min<ll>(x, D);                      // 需要显式算的 g
    for (int j = 1; j <= gm; ++j) g[j] = min(q[j], sat(s, p[j - 1]));

    int am = (int)min<ll>(x, max<ll>(0, D - x));      // 需要显式算的瞬态 a
    if (am >= 1) {
        a[1] = sat(s, q[1]);                          // a_1 = s + min(q_1, INF)
        for (int t = 2; t <= am; ++t) a[t] = sat(s, min(q[t], a[1]));
    }

    for (int j = 0; j < x; ++j) {
        ll o = D - x + j;                             // 目标格相对平台起点的偏移
        if (o < 0) { u[j] = w[D + j]; continue; }      // 落在平台之前：值原样搬过来
        ll jj = o + 1;                                // 1-based 偏移
        if (jj <= x) { u[j] = g[jj]; continue; }
        ll uu = jj - x;                               // g_jj = a_{jj-x}
        if (uu <= x) { u[j] = a[uu]; continue; }
        u[j] = sat(a[(uu - 1) % x + 1], s * ((uu - 1) / x));
    }
}

// ---------------------------------------------------------------
// min-plus 矩阵：mat[out][in]，作用 out[j] = min_i(mat[j][i] + v[i])
// ---------------------------------------------------------------
struct Mat { ll v[MAXK][MAXK]; };

static void matApply(const Mat &m, const ll *w, ll *out) {
    for (int j = 0; j < X; ++j) {
        ll best = INF;
        for (int i = 0; i < X; ++i) best = min(best, sat(m.v[j][i], w[i]));
        out[j] = best;
    }
}
// C = A ⊗ B：先作用 B 再作用 A
static void matMul(const Mat &A, const Mat &B, Mat &C) {
    for (int j = 0; j < X; ++j)
        for (int i = 0; i < X; ++i) {
            ll best = INF;
            for (int u = 0; u < X; ++u) best = min(best, sat(A.v[j][u], B.v[u][i]));
            C.v[j][i] = best;
        }
}

static int n;
static vector<ll> D, S;
static vector<Mat> tree;
static int sz, nb;

// 重算第 blk 块的转移矩阵（对 x 个基向量各推一遍）
static void computeBlock(int blk) {
    int lo = blk * BLKSZ, hi = min(n, lo + BLKSZ);
    Mat &m = tree[sz + blk];
    ll w[MAXK], u[MAXK], t[MAXK];
    for (int i = 0; i < X; ++i) {
        for (int j = 0; j < X; ++j) w[j] = (j == i ? 0 : INF);
        ll *cur = w, *nxt = u;
        for (int p = lo; p < hi; ++p) {
            applyPlatform(D[p], S[p], cur, nxt);
            swap(cur, nxt);
        }
        for (int j = 0; j < X; ++j) m.v[j][i] = cur[j];
    }
    (void)t;
}

static void buildTree() {
    nb = (n + BLKSZ - 1) / BLKSZ;
    sz = 1;
    while (sz < nb) sz <<= 1;
    tree.assign(2 * sz, Mat());
    for (int b = 0; b < sz; ++b)
        for (int j = 0; j < X; ++j)
            for (int i = 0; i < X; ++i) tree[sz + b].v[j][i] = (j == i ? 0 : INF);  // 单位阵
    for (int b = 0; b < nb; ++b) computeBlock(b);
    for (int i = sz - 1; i >= 1; --i) matMul(tree[2 * i + 1], tree[2 * i], tree[i]);
}

// 把平台 [p, q] 的转移依次作用到向量 v 上（就地更新）
static void applyRange(int p, int q, ll *v) {
    if (p > q) return;
    ll tmp[MAXK];
    int b1 = p / BLKSZ, b2 = q / BLKSZ;
    if (b1 == b2) {
        for (int i = p; i <= q; ++i) {
            applyPlatform(D[i], S[i], v, tmp);
            memcpy(v, tmp, sizeof(ll) * X);
        }
        return;
    }
    int endB1 = (b1 + 1) * BLKSZ - 1;
    for (int i = p; i <= endB1; ++i) {
        applyPlatform(D[i], S[i], v, tmp);
        memcpy(v, tmp, sizeof(ll) * X);
    }
    if (b2 > b1 + 1) {                        // 中间的整块走线段树
        int L = b1 + 1, R = b2 - 1;
        int lo[64], hi[64], nl = 0, nr = 0;
        for (int l = L + sz, r = R + sz + 1; l < r; l >>= 1, r >>= 1) {
            if (l & 1) lo[nl++] = l++;
            if (r & 1) hi[nr++] = --r;
        }
        for (int i = 0; i < nl; ++i) {        // 从左到右依次作用
            matApply(tree[lo[i]], v, tmp);
            memcpy(v, tmp, sizeof(ll) * X);
        }
        for (int i = nr - 1; i >= 0; --i) {
            matApply(tree[hi[i]], v, tmp);
            memcpy(v, tmp, sizeof(ll) * X);
        }
    }
    for (int i = b2 * BLKSZ; i <= q; ++i) {
        applyPlatform(D[i], S[i], v, tmp);
        memcpy(v, tmp, sizeof(ll) * X);
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int q;
    if (!(cin >> n >> q >> X)) return 0;
    D.resize(n);
    S.resize(n);
    for (int i = 0; i < n; ++i) cin >> D[i];
    for (int i = 0; i < n; ++i) cin >> S[i];

    buildTree();

    string out;
    out.reserve(1 << 20);
    ll v[MAXK];
    for (int qi = 0; qi < q; ++qi) {
        char op;
        cin >> op;
        if (op == '?') {
            int l, r;
            cin >> l >> r;
            --l; --r;
            // 起点状态：从平台 l 的第一格出发（代价 0），窗口取平台 l 末尾 x 格
            for (int j = 0; j < X; ++j) {
                ll o = D[l] - X + j;                       // 相对平台起点的偏移
                if (o < 0) v[j] = INF;
                else v[j] = S[l] * ((o + X - 1) / X);      // s * ceil(o / x)
            }
            applyRange(l + 1, r, v);
            out += to_string(v[X - 1]);
            out += '\n';
        } else if (op == '1') {
            int i; ll val;
            cin >> i >> val;
            --i;
            D[i] = val;
            int blk = i / BLKSZ;
            computeBlock(blk);
            for (int node = (sz + blk) >> 1; node >= 1; node >>= 1)
                matMul(tree[2 * node + 1], tree[2 * node], tree[node]);
        } else {
            int i; ll val;
            cin >> i >> val;
            --i;
            S[i] = val;
            int blk = i / BLKSZ;
            computeBlock(blk);
            for (int node = (sz + blk) >> 1; node >= 1; node >>= 1)
                matMul(tree[2 * node + 1], tree[2 * node], tree[node]);
        }
    }
    fwrite(out.data(), 1, out.size(), stdout);
    return 0;
}
```

### 复杂度

与 F1 同阶，$x = 10$ 时取到上界：建树 $O(n x^2 + \frac{n}{B} x^3)$，单次修改 $O(x^2 B + x^3 \log \frac{n}{B})$，单次询问 $O(x B + x^2 \log \frac{n}{B})$，$B = 64$。实测：$n = 10^6$、$q = 10^4$、$x = 10$ 随机 0.841 s，$n = 10^6$、$q = 10^4$、$x = 10$ 全区+更新 0.730 s。

### 易错点

1. 两份代码是同一份，`MAXK` 必须开 10；照着 F1 的题面把它改回 5，F2 的 $x = 10$ 就会越界写数组。
2. 数组维度与循环边界要用运行期读入的 $x$（代码里读进一个全局变量，数组维度都跟着它走），不能写死 5 —— 同一份代码要同时吃下 F1/F2 的输入。
3. $x$ 变大后矩阵乘法常数涨 8 倍，块大小不能再调小；把叶子改回「一个平台一个叶子」会在建树阶段就超时。
4. `BLKSZ` 与 `MAXK` 相互独立，改 `BLKSZ` 会同时影响建树、修改（重算一块）与询问（两端逐平台）三处代价。
5. 其余同 F1：罚分只看是否同平台、初始窗口填无穷大、`matMul` 的作用顺序、`INF` 的饱和加法。

