### 手算

样例第 1 组：$n = 5$，$a = [0, 1, -1, 0, 1]$，边 $1-2,\ 1-3,\ 2-4,\ 2-5$（以 $1$ 为根）。只有点 $1$、$4$ 是 0，共 $2^2 = 4$ 种改法，直接枚举（$S_3 = 1$、$S_4 = 1$、$S_5 = 1$ 恒定）：

| $x_1$ | $x_4$ | $S_1$ | $S_2$ | $S_3 + S_4 + S_5$ | 合计 |
|---|---|---|---|---|---|
| $+1$ | $+1$ | $3$ | $3$ | $3$ | $9$ |
| $+1$ | $-1$ | $1$ | $1$ | $3$ | $\mathbf{5}$ |
| $-1$ | $+1$ | $1$ | $3$ | $3$ | $7$ |
| $-1$ | $-1$ | $1$ | $1$ | $3$ | $\mathbf{5}$ |

最小是 $5$ ✓（题面 Note 里那两个最优赋值正好就是后两行的 $x_1$ 取法 —— 注意 $x_1$ 取哪个都行，因为 $S_1$ 与 $S_2$ 同时被压到 $1$）。

样例第 2 组没有 0 可改（$a$ 全是 $\pm 1$），赋值唯一：按子树求和得 $S = [0, 1, 2, 1, 1, 0, 1, 1]$，合计 $7$ ✓。

### 思路

**DP。** 记号与四步操作见「从零讲」。按 $v$ 自己的初值分两种转移（$\chi_v$ 是孩子们 $\psi_c$ 的 $(\min,+)$ 卷积）：

- $a_v \ne 0$：$Y_v = \sum_c Y_c$，所以 $\psi_v(z) = \lvert B_v - 2z \rvert + \chi_v(z)$；
- $a_v = 0$：$v$ 自己还要出一个 $\pm 1$，$Y_v = y_v + \sum_c Y_c$（$y_v \in \{0, 1\}$），所以 $\psi_v(z) = \lvert B_v - 2z \rvert + \min\big(\chi_v(z),\ \chi_v(z-1)\big)$。

$\psi_v$ 始终是凸的（凸函数的 $(\min,+)$ 卷积、加一个凸函数、以及这个"侵蚀"都保凸），所以每一层都能用「base + 差分多重集」表示。自底向上推一遍，每个点做三件事：并孩子的表（base 相加）、$a_v = 0$ 时插一个差分 $0$、加 $\lvert B_v - 2z \rvert$（按 rank 前后各整体加 $-2$ / $+2$），最后 base 累加 $\sum_c \text{base}_c + \lvert B_v \rvert$。

**加 $\lvert B_v - 2z \rvert$ 的两个切点。** 它的差分 $\delta_z = \lvert B-2z\rvert - \lvert B-2(z-1)\rvert$ 是一条不减的三档序列：$z \le \lfloor B/2 \rfloor$ 时 $\delta_z = -2$；$z \ge \lfloor B/2 \rfloor + 2$ 时 $\delta_z = +2$；中间最多一个位置取 $0$（$B$ 为奇数时正好一个，$B$ 为偶数时没有 —— 也就是"拐点正好落在整数 $z = B/2$ 上"还是"落在两格之间"的区别）。所以差分表按升序摆好后：前 $\lfloor B/2 \rfloor$ 个各 $-2$，从下标 $\lfloor (B+1)/2 \rfloor$ 起到底各 $+2$（$B < 0$ 时全体 $+2$：$B$ 太小，$Y_v$ 越小子树和越小，往上走只会更贵），两端的下标都要按表长 $f_v$ 截断。

**答案。** 由凸性，$\psi_1$ 的负差分全在最前面，所以 $\min_z \psi_1(z) = \text{base}_1 + \sum_{\Delta < 0} \Delta$ —— 代码里把值 $\le -1$ 的元素切出来求和即可。

### 参考代码

```cpp
// F. Plus Minus Tree
// 记 A_v = 子树内固定权值和、f_v = 子树内 0 的个数；把「子树里被改成 -1 的 0 的个数」记为 Y_v，
// 则子树和 S_v = B_v - 2Y_v（B_v = A_v + f_v），代价 Σ|S_v|。
// DP：ψ_v(z) = min(子树代价 | Y_v = z) =
//        |B_v - 2z| + χ_v(z)                 （v 固定，χ_v = 孩子们 ψ 的 min-plus 卷积）
//        |B_v - 2z| + min(χ_v(z), χ_v(z-1))  （v 是 0：Y_v = y_v + Σ Y_c）
// ψ_v 是凸的。用「base = ψ_v(0) + 升序差分多重集」表示：
//   卷积 = 差分多重集并；加 |B-2z| = 按 rank 前段 -2、后段 +2（B 为奇数时中间一格不动）；
//   侵蚀 min(χ(z),χ(z-1)) = 插入一个差分 0；答案 = base + 负差分之和。
// 多重集用可合并 treap（按 (值, id) 严格全序、支持按 rank 切分与懒加），总复杂度 O(n log^2 n)。
//
// ⚠️ 键必须带唯一 id：差分里等值元素极多（全 0 树几乎全是 0），若只用数值当键，
//    BST 下降会永远走同一侧，treap 退化成 O(n) 高的链——实测全 0 完全二叉树 n=2e5 要跑 30+ 秒。
#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

struct Node {
    ll val, add, sum;
    unsigned prio, id;
    int sz;
    Node *l, *r;
};
static unsigned long long rngState = 88172645463325252ULL;
static inline unsigned rndPrio() {
    rngState ^= rngState << 13;
    rngState ^= rngState >> 7;
    rngState ^= rngState << 17;
    return (unsigned)(rngState >> 32);
}
static unsigned idCounter = 0;

// 严格全序：先比数值，再比唯一 id
static inline bool keyLess(const Node* a, const Node* b) {
    if (a->val != b->val) return a->val < b->val;
    return a->id < b->id;
}
static inline bool keyLessEq(const Node* a, const Node* b) { return !keyLess(b, a); }

static Node* newNode(ll v) {
    Node* x = new Node();
    x->val = v; x->add = 0; x->sum = v; x->prio = rndPrio(); x->id = ++idCounter; x->sz = 1;
    x->l = x->r = nullptr;
    return x;
}
static int nsz(Node* t) { return t ? t->sz : 0; }
static ll nsum(Node* t) { return t ? t->sum : 0; }
static void upd(Node* t) { if (t) { t->sz = 1 + nsz(t->l) + nsz(t->r); t->sum = t->val + nsum(t->l) + nsum(t->r); } }
static void apply(Node* t, ll d) { if (t) { t->val += d; t->add += d; t->sum += d * t->sz; } }
static void push(Node* t) { if (t && t->add) { apply(t->l, t->add); apply(t->r, t->add); t->add = 0; } }

// 按键切：a = 键 ≤ x 的，b = 键 > x 的
static void splitNode(Node* t, Node* x, Node*& a, Node*& b) {
    if (!t) { a = b = nullptr; return; }
    push(t);
    if (keyLessEq(t, x)) { splitNode(t->r, x, t->r, b); a = t; upd(a); }
    else { splitNode(t->l, x, a, t->l); b = t; upd(b); }
}
// 按数值切：a = 数值 ≤ v 的，b = 其余（等值元素全在 a 侧）
static void splitVal(Node* t, ll v, Node*& a, Node*& b) {
    if (!t) { a = b = nullptr; return; }
    push(t);
    if (t->val <= v) { splitVal(t->r, v, t->r, b); a = t; upd(a); }
    else { splitVal(t->l, v, a, t->l); b = t; upd(b); }
}
// 按 rank 切：a = 最小的 k 个（in-order 前缀）
static void splitSize(Node* t, int k, Node*& a, Node*& b) {
    if (!t) { a = b = nullptr; return; }
    push(t);
    if (nsz(t->l) >= k) { splitSize(t->l, k, a, t->l); b = t; upd(b); }
    else { splitSize(t->r, k - nsz(t->l) - 1, t->r, b); a = t; upd(a); }
}
static void insertNode(Node*& t, Node* x) {
    if (!t) { t = x; upd(t); return; }
    if (x->prio < t->prio) { push(t); splitNode(t, x, x->l, x->r); upd(x); t = x; return; }
    push(t);
    if (keyLessEq(x, t)) insertNode(t->l, x); else insertNode(t->r, x);
    upd(t);
}
static Node* mergeT(Node* a, Node* b) {
    if (!a) return b;
    if (!b) return a;
    if (a->prio < b->prio) { push(a); a->r = mergeT(a->r, b); upd(a); return a; }
    push(b); b->l = mergeT(a, b->l); upd(b); return b;
}
// 按 rank 区间 [lo,hi) 整体加 d
static void addRange(Node*& t, int lo, int hi, ll d) {
    if (lo >= hi || !t) return;
    Node *a, *b, *c;
    splitSize(t, lo, a, b);
    splitSize(b, hi - lo, b, c);
    apply(b, d);
    t = mergeT(mergeT(a, b), c);        // 三段按序接回（a ≤ b ≤ c）
}
// 两个 treap 求并（键全域可比，O(m log(n/m))）
static Node* unite(Node* a, Node* b) {
    if (!a) return b;
    if (!b) return a;
    if (a->prio < b->prio) {
        push(a);
        Node *b1, *b2;
        splitNode(b, a, b1, b2);
        a->l = unite(a->l, b1);
        a->r = unite(a->r, b2);
        upd(a);
        return a;
    }
    push(b);
    Node *a1, *a2;
    splitNode(a, b, a1, a2);
    b->l = unite(a1, b->l);
    b->r = unite(a2, b->r);
    upd(b);
    return b;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int tc;
    cin >> tc;
    while (tc--) {
        int n;
        cin >> n;
        vector<int> a(n + 1);
        for (int i = 1; i <= n; i++) cin >> a[i];
        vector<vector<int>> adj(n + 1);
        for (int i = 0; i < n - 1; i++) {
            int u, v;
            cin >> u >> v;
            adj[u].push_back(v);
            adj[v].push_back(u);
        }
        vector<int> order;
        vector<char> vis(n + 1, 0);
        vector<int> par(n + 1, 0);
        order.push_back(1); vis[1] = 1;
        for (size_t i = 0; i < order.size(); i++) {
            int u = order[i];
            for (int w : adj[u]) if (!vis[w]) { vis[w] = 1; par[w] = u; order.push_back(w); }
        }
        vector<vector<int>> ch(n + 1);
        for (int v = 2; v <= n; v++) ch[par[v]].push_back(v);

        vector<ll> A(n + 1, 0);
        vector<int> F(n + 1, 0);
        for (int i = n - 1; i >= 0; i--) {
            int v = order[i];
            if (a[v] != 0) A[v] += a[v]; else F[v] += 1;
            for (int c : ch[v]) { A[v] += A[c]; F[v] += F[c]; }
        }

        vector<Node*> T(n + 1, nullptr);
        vector<ll> base(n + 1, 0);
        for (int i = n - 1; i >= 0; i--) {
            int v = order[i];
            for (int c : ch[v]) {
                T[v] = unite(T[v], T[c]);
                base[v] += base[c];
            }
            if (a[v] == 0) {                       // 侵蚀：min(χ(z), χ(z-1)) => 插一个 0
                insertNode(T[v], newNode(0));
            }
            ll B = A[v] + F[v];
            base[v] += llabs(B);
            int len = nsz(T[v]);
            ll c1raw = (B >= 2) ? ((B - 2) / 2 + 1) : 0;
            ll c2raw = (B >= 0) ? ((B + 1) / 2) : -((-B) / 2);
            int c1 = (int)max<ll>(0, min<ll>(len, c1raw));
            int c2 = (int)max<ll>(0, min<ll>(len, c2raw));
            if (c1 > c2) c1 = c2;
            addRange(T[v], 0, c1, -2);
            addRange(T[v], c2, len, 2);
        }
        ll ans = base[1];
        Node *neg = nullptr, *rest = nullptr;
        splitVal(T[1], -1, neg, rest);
        ans += nsum(neg);
        cout << ans << "\n";
    }
    return 0;
}
```

### 复杂度

时间 $O(n \log^{2} n)$ 以内：每个点做常数次 $O(\log n)$ 的操作（插入一个差分、两次按 rank 的区间加），treap 的并合计 $O(n \log n)$ 级，每个点还要 BFS 定序（线性）。空间 $O(n)$。实测 $n = 2\times10^{5}$ 最慢 0.230 s（全 0 链）、随机树 0.152 s、全 0 完全二叉树 0.123 s、全 0 星形 0.083 s，限时 3 s。

### 易错点

1. **差分多重集的键只写数值、不带唯一 id**：差分里等值元素极多（全 0 树几乎全是 $0$），BST 下降会永远走同一侧，treap 退化成 $O(n)$ 高的链。实测旧版（只用数值当键）在 $n = 2\times10^{5}$ 的全 0 **完全二叉树**上要 30~65 s —— 当时"通过"是因为极限用例只测了链和随机树、没覆盖病态形态；改成「值 + 唯一 id」严格全序 + 真正的 treap 并之后，全部形态 $\le 0.23$ 秒。
2. **侵蚀那一格漏插 / 多插**：$a_v = 0$ 时是 $\min\big(\chi(z), \chi(z-1)\big)$，要在差分表里插一个 $0$（差分个数才与 $f_v$ 对得上）；写成 $\chi(z)$ 就是把"$v$ 自己那个 $\pm 1$"丢了。
3. **区间加按"值"切而不是按 rank 切**：要加的是"升序第前 $c_1$ 个 / 第 $c_2$ 个往后"，等值元素一大片，按值切会把它们切错位置（这正是易错点 1 那个键设计的同一条道理）。
4. **base 与答案**：base 要按 $\sum_c \text{base}_c + \lvert B_v \rvert$ 累加；答案 $=$ base $+$ 所有负差分之和（凸性保证"负的全取"最优），只加一部分、或者忘了加负差分都不对。
5. **懒标记不下推**：按 rank 切分、插入、并之前都要 `push`，漏一次就让整体加的差值串到别的子树里；另外 $n$ 到 $2\times10^{5}$，定根别用递归 DFS（代码里用手写 BFS 队列定序，再倒着推）。

