        ┃ ━━━━━━━━━ ┃

      0   0   0   0   0     R=1、B=0 已是 clean

      ━━━━━━━━━━━━━━━━━
  → 用了 2 次，恰好等于 ceil(B/2) = 2：这几步每次都把 R 减了 2（R 只剩两段时最后一步只减 1，这两个例子都没走到那一步）。

  t = 1011：R = 3、B = 2，预期 ceil(B/2) = 1 次。
         ┌─┐

      1   0   1   1     R=3、B=2  ← 翻中间那段（下标 1..1）

        ┃   ┃ ━━━━━

      1   1   1   1     R=1、B=0 已是 clean

      ━━━━━━━━━━━━━
  → 用了 1 次，恰好等于 ceil(B/2) = 1：这几步每次都把 R 减了 2（R 只剩两段时最后一步只减 1，这两个例子都没走到那一步）。
```

### 手算

以题面第一组样例 $s = \texttt{110}$ 为例，把它的 6 个子串逐个算一遍：

| 子串 | $B$ | beauty |
|---|---|---|
| $1$、$1$、$0$ | 0 | 0 |
| $11$ | 0 | 0 |
| $10$ | 1 | 1 |
| $110$ | 1 | 1 |

power $= 0+0+0+0+1+1 = 2$，与题面给出的 $2$ 一致。

### 思路

$\lceil B/2 \rceil$ 里那个「向上取整」不好直接求和，把它拆成整数的一半：

$$\textit{power}(s) = \frac{1}{2}\Bigl(\sum_{\text{全部子串}} B \;+\; K\Bigr),$$

其中 $K$ 是「$B$ 为奇数」的子串个数（$B$ 偶时 $B/2$ 正好，$B$ 奇时补上那个 $1$ 再除以 $2$）。两块分别算。

**第一块 $\sum B$：按「相邻对」拆。** 令 $d_i = [s_i \ne s_{i+1}]$（$1 \le i < n$），子串 $[l,r]$ 的 $B = d_l + d_{l+1} + \cdots + d_{r-1}$。交换求和次序，问「$d_i$ 被多少个含它的子串数到」：左端可取 $1..i$ 共 $i$ 种、右端可取 $i+1..n$ 共 $n-i$ 种，于是

$$\sum_{\text{全部子串}} B = \sum_{i=1}^{n-1} d_i \cdot i \cdot (n-i).$$

**第二块 $K$：用前缀奇偶。** 令 $P(k) = d_1 \oplus d_2 \oplus \cdots \oplus d_k$（$P(0) = 0$，$\oplus$ 是异或）。子串 $[l,r]$ 的 $B$ 的**奇偶**等于 $P(r-1) \oplus P(l-1)$：$B$ 为奇数 $\iff$ 这两个前缀的奇偶不同。把 $x = l-1 < y = r-1$ 看成 $[0, n-1]$ 里的一对下标，取值不同的下标对恰好有 $c_0 \cdot c_1$ 对（$c_0, c_1$ 是 $P(0), \dots, P(n-1)$ 里 $0$ 与 $1$ 的个数），所以

$$K = c_0 \cdot c_1 .$$

**修改怎么维护。** 翻转 $s_p$ 只可能改动 $d_{p-1}$ 与 $d_p$ 两项：$\sum B$ 那部分直接按 $i(n-i)$ 加减即可。而某个 $d_j$ 一旦改变，$P(k)$ 在 $k \ge j+1$ 的整段**一起取反**（异或的链式影响），所以需要一个支持「区间 0/1 取反、问全局 0 的个数」的结构 —— 线段树 + 懒标记：结点存该区间里 $0$ 的个数，整段取反时它变成「区间长度 $-$ 原值」。线段树与懒标记在《周赛 157》F 题「从零讲：线段树与懒标记」节讲过，这里直接拿来用。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

// 结论 1：一个二进制串 t 的 beauty = ceil(B/2)，B = 相邻不同字符的对数。
//   每次操作选一段「全同」的子串翻转，只会改变它两个端点外侧的相邻关系，
//   即最多消掉 2 个 B；而相邻的两个不同对 (i, i+1) 可以靠翻转单字符 i+1 一次消掉，
//   所以下界 ceil(B/2) 能取到。
// 结论 2：power = sum over 子串 ceil(B/2) = ( sum B + #(B 为奇数的子串) ) / 2。
//   sum B = sum_i d_i * i * (n - i)，d_i = [s_i != s_{i+1}]（1 起始）。
//   #(B 为奇数) = 前缀异或 P(k) = d_1 ^ ... ^ d_k 中，取值 0 与 1 的个数之积。
//   翻转 s_i 只会让 P(i..n-1) 全部取反，于是用「区间翻转 + 维护 0 的个数」的线段树即可。

int N;                          // 线段树区间 [0, N-1]
vector<int> zeroCnt, segLen;
vector<char> lazyFlip;

void build(int node, int l, int r, const vector<int> &P) {
    segLen[node] = r - l + 1;
    lazyFlip[node] = 0;
    if (l == r) { zeroCnt[node] = (P[l] == 0); return; }
    int m = (l + r) / 2;
    build(node * 2, l, m, P);
    build(node * 2 + 1, m + 1, r, P);
    zeroCnt[node] = zeroCnt[node * 2] + zeroCnt[node * 2 + 1];
}

void applyFlip(int node) {                     // 整个区间取反：0 的个数变成 1 的个数
    zeroCnt[node] = segLen[node] - zeroCnt[node];
    lazyFlip[node] ^= 1;
}

void pushDown(int node) {
    if (lazyFlip[node]) {
        applyFlip(node * 2);
        applyFlip(node * 2 + 1);
        lazyFlip[node] = 0;
    }
}

void rangeFlip(int node, int l, int r, int ql, int qr) {
    if (qr < l || r < ql) return;
    if (ql <= l && r <= qr) { applyFlip(node); return; }
    pushDown(node);
    int m = (l + r) / 2;
    rangeFlip(node * 2, l, m, ql, qr);
    rangeFlip(node * 2 + 1, m + 1, r, ql, qr);
    zeroCnt[node] = zeroCnt[node * 2] + zeroCnt[node * 2 + 1];
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int tc;
    cin >> tc;
    while (tc--) {
        int n, q;
        string s;
        cin >> n >> q >> s;

        N = n;
        zeroCnt.assign(4 * max(n, 1) + 4, 0);
        segLen.assign(4 * max(n, 1) + 4, 0);
        lazyFlip.assign(4 * max(n, 1) + 4, 0);

        vector<int> d(max(n - 1, 0), 0);       // d[i] = [s[i] != s[i+1]]，0 起始
        long long S = 0;                       // sum B
        for (int i = 0; i + 1 < n; i++) {
            d[i] = (s[i] != s[i + 1]);
            if (d[i]) S += (long long)(i + 1) * (n - 1 - i);
        }
        vector<int> P(n, 0);                   // P[k] = d[0] ^ ... ^ d[k-1]
        for (int k = 1; k < n; k++) P[k] = P[k - 1] ^ d[k - 1];
        build(1, 0, n - 1, P);

        auto answer = [&]() -> long long {
            long long c0 = zeroCnt[1], c1 = (long long)n - c0;
            return (S + c0 * c1) / 2;
        };

        cout << answer();
        for (int qi = 0; qi < q; qi++) {
            int pos;
            cin >> pos;
            int p = pos - 1;                   // 0 起始的翻转位置
            s[p] = (s[p] == '0' ? '1' : '0');
            for (int j = p - 1; j <= p; j++) { // 只有这两对相邻关系会变
                if (j < 0 || j + 1 >= n) continue;
                int nv = (s[j] != s[j + 1]);
                if (nv != d[j]) {
                    S += (long long)(nv ? 1 : -1) * (j + 1) * (n - 1 - j);
                    d[j] = nv;
                    rangeFlip(1, 0, n - 1, j + 1, n - 1);   // d[j] 影响 P[j+1..n-1]
                }
            }
            cout << ' ' << answer();
        }
        cout << '\n';
    }
    return 0;
}
```

### 复杂度

每组 $O((n+q)\log n)$ 时间（$q$ 次单点取反各带一次 $O(\log n)$ 的区间取反）、$O(n)$ 空间。

### 易错点

- 线段树维护的是**前缀奇偶串 $P$**（共 $n$ 个值），不是原串；$d_j$ 改变时取反的是 $P$ 的下标区间 $[j+1, n-1]$，差一位最容易写错。
- 翻转位置在两端时只有一对相邻关系会变（$p=1$ 没有 $d_0$，$p=n$ 没有 $d_n$），循环里两个候选下标都要判越界。
- $n = 1$ 时没有任何相邻对：$\sum B = 0$、$P$ 只有 $P(0)=0$，$c_0 c_1 = 0$，power 恒为 $0$；线段树至少要能容下 1 个叶子。
- 答案是 $\dfrac{\sum B + c_0 c_1}{2}$，两项都是整数不用管取整；但 $\sum B$ 最大到 $n^3/6$ 量级（$n = 2\cdot10^5$ 时约 $1.3\times10^{15}$），累加必须用 `long long`。

