图 3 · 关系是严格偏序，答案就是「按 T 排好队」的最长链
======================================================================

  由类时推出来的三角形不等式保证了传递性：i 与 j 独立、j 与 k 独立，则 i 与 k 也独立。
  于是把 i ≺ j 定义成「T_i < T_j 且 i、j 独立」，它就是一个严格偏序，
  「两两独立的集合」正好是它的一条链。

  T[i] = a_i + c_i（i = 1..4）
  i[]          1    2    3    4
  T[]          0   -6   -6   -3
  按 T 从小到大排：f2(T=-6) -> f3(T=-6) -> f4(T=-3) -> f1(T=0)

         函数         T   down（以它结尾的最长链）  up（以它开头的最长链）    算式     答案
  ──────────────────  ──  ────────────────────────  ──────────────────────  ─────────  ────
  f1 = x^2 + 2x - 1    0             3                        1             3 + 1 - 1   3
  f2 = -3x^2 - 3      -6             1                        2             1 + 2 - 1   2
  f3 = -x^2 + 4x - 5  -6             1                        3             1 + 3 - 1   3
  f4 = x^2 + 2x - 4   -3             2                        2             2 + 2 - 1   3

  f1 那一行：down(f1) = 3 来自链 f3 -> f4 -> f1（或 f2 -> f1 再接不上更长的），
  up(f1) = 1，合起来 3 + 1 - 1 = 3，正是题目要的「含 f1 的最大 organized 子集」。
  f2 只能和 f1 配，所以是 2；f3、f4 与 f1 三个凑成 {f1, f3, f4}，也是 3。
```

### 手算

把样例 1 的独立关系画出来：$f_1$ 与 $f_2, f_3, f_4$ 都独立，$f_3$ 与 $f_4$ 独立，$f_2$ 与 $f_3, f_4$ 都相交。于是

- 含 $f_1$ 的最长链：$f_3 \prec f_4 \prec f_1$（三点两两独立）→ 3；
- 含 $f_2$ 的：只有 $f_2 \prec f_1$ → 2；
- 含 $f_3$ 的：$f_3 \prec f_4 \prec f_1$ → 3；
- 含 $f_4$ 的：$f_3 \prec f_4 \prec f_1$ → 3。

输出 3 2 3 3，与样例一致 ✓。样例第 2、3 组依次是 3 3 2 2 3 和 3 3 3 1 2。

### 思路

1. 读入 $(a, b, c)$，算出 $T = a + c$、$P = b$、$Q = a - c$（判据里还要用到 $a$，留着）。
2. 独立判据：先算 $\Delta P, \Delta Q, \Delta T$，若 $\Delta P^2 + \Delta Q^2 < \Delta T^2$ 直接返回真；否则返回「$\Delta a = 0$ 且 $\Delta b = 0$」。
3. 把下标按 $T$ 从小到大排序。**独立的一对必然 $T$ 不同**：若 $T$ 相同又独立，要么要求平方和小于 $0$（不可能），要么走例外分支 —— 那意味着 $a$ 也相同，$T = a + c$ 又相同就推出 $c$ 相同，两个函数完全一样，与「两两不同」矛盾。
4. 正序扫一遍求 $down$（只看排在前面、且与它独立的点），倒序扫一遍求 $up$。
5. 输出 $down[i] + up[i] - 1$。

### 参考代码

```cpp
// F. Parabola Independence
//
// 两个抛物线 f_i, f_j 独立 <=> 方程 f_i(x) = f_j(x) 没有实数解。
// 记 A=Δa, B=Δb, C=Δc（都是两个函数之差）：
//   · A = 0：一次方程 Bx + C = 0，无解 <=> B = 0（此时两函数是上下平移，永不相交）；
//   · A ≠ 0：判别式 B^2 - 4AC < 0。
//
// 关键恒等式：B^2 - 4AC = B^2 + (A-C)^2 - (A+C)^2。
// 把每个函数映成三维点 (T, P, Q) = (a+c, b, a-c)，则
//   「独立」<=> P、Q 方向的欧氏距离 < |ΔT|  （即闵可夫斯基意义下的「类时」），
//   例外是 A = B = 0（上下平移）—— 这时恰好取等号，但两点确实不相交。
//
// 因为「类时」满足三角形不等式推出的传递性（严格步与取等步混着也成立），
// 关系  i ≺ j  <=>  T_i < T_j 且 i、j 独立   是一个**严格偏序**，
// 于是「两两独立的集合」= 偏序里的链，答案是
//   s_i = down[i] + up[i] - 1
// （down[i] = 以 i 结尾的最长链，up[i] = 以 i 开头的最长链）。
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);       // 只用 cin/cout，不碰 stdio
    cin.tie(nullptr);

    int t;
    cin >> t;                          // 测试组数
    while (t--) {
        int n;
        cin >> n;                      // 抛物线个数
        vector<long long> A(n), P(n), Q(n), T(n);   // A = a, P = b, Q = a-c, T = a+c
        for (int i = 0; i < n; i++) {
            long long a, b, c;
            cin >> a >> b >> c;        // f_i(x) = a x^2 + b x + c
            A[i] = a;
            P[i] = b;
            Q[i] = a - c;
            T[i] = a + c;
        }

        // 独立判据：ΔP^2 + ΔQ^2 < ΔT^2，或（A 与 P 都相同 => 纯上下平移）
        auto independent = [&](int i, int j) -> bool {
            long long dP = P[i] - P[j];
            long long dQ = Q[i] - Q[j];
            long long dT = T[i] - T[j];
            if (dP * dP + dQ * dQ < dT * dT) return true;
            return A[i] == A[j] && P[i] == P[j];
        };

        // 按 T 排序：独立的一对必然 T 不同，所以同 T 之间没有边
        vector<int> ord(n);
        iota(ord.begin(), ord.end(), 0);
        sort(ord.begin(), ord.end(), [&](int x, int y) { return T[x] < T[y]; });

        vector<int> down(n, 1), up(n, 1);          // 链长度初值 = 只有自己
        for (int i = 0; i < n; i++) {              // 正序：算 down
            int v = ord[i];
            int best = 0;
            for (int k = 0; k < i; k++) {
                int u = ord[k];
                if (T[u] < T[v] && independent(u, v)) best = max(best, down[u]);
            }
            down[v] = best + 1;
        }
        for (int i = n - 1; i >= 0; i--) {         // 倒序：算 up
            int v = ord[i];
            int best = 0;
            for (int k = i + 1; k < n; k++) {
                int u = ord[k];
                if (T[u] > T[v] && independent(v, u)) best = max(best, up[u]);
            }
            up[v] = best + 1;
        }

        for (int i = 0; i < n; i++) {              // 含 f_i 的最长链
            cout << down[i] + up[i] - 1 << (i + 1 == n ? '\n' : ' ');
        }
    }
    return 0;
}
```

### 复杂度

$O(n^2)$ 时间（两两比较），$O(n)$ 空间；$n \le 3000$ 且 $\sum n^2 \le 3000^2$。

### 易错点

1. **例外分支不能省。** $\Delta a = \Delta b = 0$（纯上下平移）时 $\Delta P^2 + \Delta Q^2 = \Delta T^2$ 取等号，但两点确实独立。漏掉这一条，样例 1 里 $f_1$ 与 $f_4$ 会被判成相交，$f_1$ 的答案从 3 掉到 2 —— 样例当场红。
2. **平方要 `long long`。** $a, b, c$ 到 $10^6$，$\Delta T$ 到 $2 \times 10^6$，平方到 $4 \times 10^{12}$，`int` 直接溢出。代码里 $P, Q, T$ 三个数组和判据里的差都按 `long long` 存。
3. 排序后同 $T$ 的点之间不该有边，所以扫描条件写的是严格不等号（$T_u < T_v$ / $T_u > T_v$）。写成 $\le$ / $\ge$ 会让同 $T$ 的点互相接上，链变长、答案偏大。
4. 排序依据是 $T$，不是下标也不是别的量；$down$ / $up$ 的初值都是 1（只有自己）。
5. 判据里的 $\Delta a$ 是 $a_i - a_j$ 而不是 $T$ 的差 —— 例外分支要判「$\Delta a = 0$ **且** $\Delta b = 0$」两条，只判一条会把「共点但开口不同的两抛物线」误判成独立。

