### 手算

拿题面红字标出的三条（都是样例第 2 组）走一遍。先备好数：$T = (9, 10, 14, 15, 15)$ 对应点 $(1,2,3,4,5)$，$\operatorname{astart} = (0, 1, 3, 4, 6)$，$pos = [1,2,1,3,4,3,5,3,1,0]$。

| 询问 | $T_v$ | $X = T_v - k$ | 最高且 $T \ge X$ 的祖先 $u$ | $\tau = k - (T_v - T_u)$ | 查表 | 答案 |
|---|---|---|---|---|---|---|
| $(3, 6)$ | 14 | 8 | $1$（$T_1 = 9 \ge 8$，再往上 $T_0 = 0$ 不够） | $6 - 5 = 1$ | $pos[0 + 1]$ | 2 |
| $(3, 8)$ | 14 | 6 | $1$ | $8 - 5 = 3$ | $pos[3]$ | 3 |
| $(3, 11)$ | 14 | 3 | $1$ | $11 - 5 = 6$ | $pos[6]$ | 5 |

三条分别是顶点 $2$、$3$、$5$，与题面给的完全一致 ✓（这一组 5 个询问的输出是 2 3 5 2 1）。

### 思路

1. 和 E 题一样：登记父亲、拿 BFS 序、逆序算 $\operatorname{size}$、正序算 $cost[v] = 2\operatorname{size}(v) - 1$ 与 $T[v]$。
2. 正序推 $\operatorname{astart}$：左孩子接在父亲后面一步，右孩子再接在「左子树整趟」之后。
3. 模拟从 $1$ 出发的 $2n-1$ 步，落点存进 $pos[]$（用一个 0/1/2 的 `mark[]` 记当前字母）。
4. 建倍增表 $up[j][v]$（第 $2^j$ 个祖先）。
5. 每个询问：算 $X = T_v - k$，从 $v$ 往上跳到「$T \ge X$」的最高祖先 $u$，输出 $pos[\operatorname{astart}(u) + k - (T_v - T_u)]$。

### 参考代码

```cpp
// G. Idiot First Search and Queries
//
// 与 E 同一套背景，先把「全局走位表」钉死，再做询问。
//
// 1) 记 cost(v) = 2*size(v) - 1（size = 子树点数）：从 v 出发、子树全空时，
//    「走完整棵子树并从 v 跨到父亲」的步数。它的第一段是左子树的整趟、
//    第二段是右子树的整趟，第三段是走上父亲，故 cost(v) = cost(l)+cost(r)+3。
// 2) 从 v 出发的实际过程 = 依次做「子树 v 的一趟、子树 par(v) 的一趟、…、子树 1 的一趟」。
//    第 j 趟的起点时刻是 S_j = T(v) - T(u_j)，其中 u_0 = v, u_1 = par(v), …, T(u) = 到 0 的总步数。
//    问「走 k 步后在哪」=> 找**最高**的祖先 u 使 T(u) >= T(v) - k（同 T 的祖先里取最靠上那个），
//    再在该趟里按局部时刻 tau = k - (T(v) - T(u)) 查表。
// 3) 关键：任何一棵子树的「一趟」都**逐字等于**从顶点 1 出发那一趟里对应的一段
//    （因为进入子树时它一定是全空的，行为只取决于子树内部）。
//    所以只需模拟一次「从 1 出发」的 2n-1 步，得到 pos[0..2n-1]；
//    子树 u 那一趟的起点是 a(u)，于是答案 = pos[a(u) + tau]。
//    a(1) = 0，左儿子 a = a(p)+1，右儿子 a = a(p)+2+cost(左儿子)。
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);        // 只用 cin/cout，不碰 stdio
    cin.tie(nullptr);

    int t;
    cin >> t;                           // 测试组数
    while (t--) {
        int n, q;
        cin >> n >> q;                  // n 个点（除根 0 外）、q 个询问
        vector<int> lc(n + 1, 0), rc(n + 1, 0), par(n + 1, 0);
        for (int i = 1; i <= n; i++) {
            cin >> lc[i] >> rc[i];
            if (lc[i]) {                // 有儿子就两个都有（题面保证）
                par[lc[i]] = i;
                par[rc[i]] = i;         // 顶点 1 的父亲保持 0
            }
        }

        // BFS 序：保证父亲排在儿子前面
        vector<int> ord;
        ord.reserve(n);
        ord.push_back(1);
        for (size_t h = 0; h < ord.size(); h++) {
            int v = ord[h];
            if (lc[v]) {
                ord.push_back(lc[v]);
                ord.push_back(rc[v]);
            }
        }

        // 逆序求子树大小，再正序求 cost 与 T
        vector<int> sz(n + 1, 0);
        vector<long long> cost(n + 1, 0), T(n + 1, 0);
        for (int i = n - 1; i >= 0; i--) {
            int v = ord[i];
            sz[v] = 1 + sz[lc[v]] + sz[rc[v]];
        }
        for (int i = 0; i < n; i++) {
            int v = ord[i];
            cost[v] = 2LL * sz[v] - 1;              // 走完整棵子树并跨出 v
            T[v] = T[par[v]] + cost[v];             // T[0] = 0
        }

        // 窗口起点 a(v)：子树 v 那一趟在「从 1 出发」那一趟里的起始时刻
        vector<long long> astart(n + 1, 0);
        for (int i = 0; i < n; i++) {
            int v = ord[i];
            if (lc[v]) {
                astart[lc[v]] = astart[v] + 1;                       // 第 1 步去左儿子
                astart[rc[v]] = astart[v] + 2 + cost[lc[v]];         // 左子树整趟后再去右儿子
            }
        }

        // 模拟从顶点 1 出发的 2n-1 步：pos[s] = 第 s 步之后所在的顶点
        vector<int> pos(2 * n + 1, 0);
        vector<unsigned char> mark(n + 1, 0);       // 0 空 / 1 'L' / 2 'R'
        int cur = 1;
        pos[0] = 1;
        for (int s = 1; s <= 2 * n - 1; s++) {
            if (lc[cur] == 0) {                     // 叶子：回父亲
                cur = par[cur];
            } else if (mark[cur] == 0) {            // 空：写 L，去左儿子
                mark[cur] = 1;
                cur = lc[cur];
            } else if (mark[cur] == 1) {            // L：改写 R，去右儿子
                mark[cur] = 2;
                cur = rc[cur];
            } else {                                // R：擦掉，回父亲
                mark[cur] = 0;
                cur = par[cur];
            }
            pos[s] = cur;                           // 最后一步落在 0 上
        }

        // 二进制跳表：up[k][v] = v 的第 2^k 个祖先（0 表示不存在）
        const int LOG = 20;                         // 2^19 = 524288 > 300001
        vector<vector<int>> up(LOG, vector<int>(n + 1, 0));
        for (int v = 1; v <= n; v++) up[0][v] = par[v];
        for (int k = 1; k < LOG; k++)
            for (int v = 1; v <= n; v++) up[k][v] = up[k - 1][up[k - 1][v]];

        string out;
        out.reserve((size_t)q * 8);
        bool first = true;                          // 一组测例的 q 个答案打在同一行
        while (q--) {
            int v;
            long long k;
            cin >> v >> k;                          // 保证 k < min(1e9+7, T(v))
            long long X = T[v] - k;                 // 本趟的祖先 u 满足 T(u) >= X
            int u = v;                              // 往上跳到「T 仍 >= X」的最高祖先
            for (int j = LOG - 1; j >= 0; j--) {
                int anc = up[j][u];
                if (anc != 0 && T[anc] >= X) u = anc;
            }
            long long tau = k - (T[v] - T[u]);      // 在本趟里的局部时刻
            if (!first) out += ' ';
            first = false;
            out += to_string(pos[astart[u] + tau]);
        }
        out += '\n';
        cout << out;
    }
    return 0;
}
```

### 复杂度

预处理 $O(n \log n)$（倍增表），每个询问 $O(\log n)$；总 $O\bigl((n + q) \log n\bigr)$，空间 $O(n \log n)$。$\sum n \le 300001$、$\sum q \le 4 \times 10^5$。

### 易错点

1. **一组测例的 $q$ 个答案要打在同一行**（样例就是一行 $q$ 个数）。逐个换行会和样例逐字不一致 —— 这题只是格式问题，但会当场 WA。
2. 倍增表层数要够：$n$ 最大 $300001$，$2^{19} = 524288$ 才罩得住，所以 `LOG` 取 20（下标 $0 \sim 19$）。开小了会跳不到根方向，答案随机错。
3. 跳祖先时条件里**必须带 `anc != 0`**：表里 $0$ 表示「没有这个祖先」，而 $T_0 = 0$ 恰好是个合法数值，$X = 0$ 时会把 $0$ 误当成合法祖先。
4. $T$ 与 $k$ 都用 `long long`。虽然 $k < 10^9+7$，但 $T$ 的真实值可以很大（递推里取了模，但比较用的是取模后的值 —— 注意题目保证 $k < \min(10^9+7, \tau_v)$，正是为了让「取模后的 $T$」和真实 $T$ 在这段比较里等价）。
5. 模拟那一趟的循环上界是 $2n-1$，别写成 $2n$：多走一步会从 $0$ 再出发，把表污染掉。
6. 用 `unsigned char` 存 `mark[]` 只是省内存，三态 0/1/2 的判断顺序别搞混（先判叶子，再判空、`'L'`、`'R'`）。

