      ──────────  ───────────────────  ──────────────────
      (  1, 0)      1 + 0 = 1            67
      (100, 0)      100 + 0 = 100        100
      ( 62, 1)      62 + 7 = 69          69

  与官方样例输出 67 100 69 一致。

  顺带解释第 3 组数字为什么是 69 而不是 67 + 6 + 7 = 80：
  买了 (62,1) 之后若想用自家 2 个，就要自家 y ≥ 2 —— 而自家最多只有 y = 1，
  所以最多只能带 1 个自家粒子，取最大的 7，答案 = 62 + 7 = 69。

  （第 2 部分结束）
```

### 参考代码

```cpp
// F. Mooclear Reactor 2
// 题意：n 个粒子 (x,y)，选子集 S 使每个被选粒子满足「其它被选粒子数 ≤ y」，收益 = x 之和；
//       商店里每个粒子（买且只买它一个）分别求最大收益（买了可以不用）。
//
// 关键：若用的自家粒子数为 s，则要求这些粒子的 y ≥ s-1（自家单独用时），
//       若把买来的粒子也算进去（总数 s+1），则要求自家粒子 y ≥ s 且商店粒子 y ≥ s。
//       所以预处理两个数组：
//         T[s]    = 从「y ≥ s」的自家粒子中取 s 个的最大和   （买来的粒子在用时的口径）
//         A[s-1]  = 从「y ≥ s-1」的自家粒子中取 s 个的最大和 （不用买来的粒子时的口径）
//       两个数组都用「按 y 降序扫描 + 小根堆维护前 k 大」在 O(n log n) 求出。
//       每个商店粒子 (x,y) 的答案 = max(基准, x + max_{0≤s≤min(y,n)} T[s])。
#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
const ll NEG = LLONG_MIN / 4;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int T;
    cin >> T;
    while (T--) {
        int n, m;
        cin >> n >> m;
        vector<pair<int, ll>> her(n);              // (y, x)
        for (int i = 0; i < n; ++i) {
            ll x; int y;
            cin >> x >> y;
            her[i] = make_pair(y, x);
        }
        // 按 y 从大到小排序：y ≥ 阈值 的粒子就是前缀
        sort(her.begin(), her.end(),
             [](const pair<int, ll>& a, const pair<int, ll>& b) { return a.first > b.first; });

        // T[s]：取自「y ≥ s」的 s 个粒子的最大能量和（取不满记 NEG）
        vector<ll> T(n + 1, NEG);
        {
            priority_queue<ll, vector<ll>, greater<ll>> pq;   // 小根堆，堆内是当前选中的和最大的一批
            ll sum = 0;
            int idx = 0;
            for (int s = n; s >= 0; --s) {
                while (idx < n && her[idx].first >= s) {      // 新加入「y ≥ s」的粒子
                    pq.push(her[idx].second);
                    sum += her[idx].second;
                    ++idx;
                }
                while ((int)pq.size() > s) {                  // 只保留最大的 s 个
                    sum -= pq.top();
                    pq.pop();
                }
                if ((int)pq.size() == s) T[s] = sum;          // 候选不足 s 个 → 该 s 不可行
            }
        }
        // 基准答案：不用商店粒子，s 个自家粒子要求 y ≥ s-1
        ll base = 0;
        {
            priority_queue<ll, vector<ll>, greater<ll>> pq;
            ll sum = 0;
            int idx = 0;
            for (int t = n - 1; t >= 0; --t) {                // t = s-1
                while (idx < n && her[idx].first >= t) {
                    pq.push(her[idx].second);
                    sum += her[idx].second;
                    ++idx;
                }
                while ((int)pq.size() > t + 1) {
                    sum -= pq.top();
                    pq.pop();
                }
                if ((int)pq.size() == t + 1) base = max(base, sum);
            }
        }
        // T 的前缀最大：max_{0≤s≤k} T[s]
        vector<ll> pref(n + 1, NEG);
        for (int s = 0; s <= n; ++s) {
            pref[s] = T[s];
            if (s) pref[s] = max(pref[s], pref[s - 1]);
        }
        // 逐个商店粒子回答
        for (int j = 0; j < m; ++j) {
            ll x; int y;
            cin >> x >> y;
            if (j) cout << ' ';
            ll k = min<ll>(y, n);                            // 自家最多用 min(y,n) 个
            ll best = base;
            if (pref[k] > NEG / 2) best = max(best, x + pref[k]);
            cout << best;
        }
        cout << '\n';
    }
    return 0;
}
```

### 复杂度

排序 $O(n \log n)$，两张表各 $O(n \log n)$（堆操作），回答商店粒子 $O(m)$；$\sum n, \sum m \le 2 \times 10^5$，空间 $O(n)$。

### 易错点

- **买了可以不用**：答案是 $x + \texttt{pref}[\min(y,n)]$ 与基准 $base$ 的较大者。样例第 1 组第 1 个商店粒子 $(1, 0)$ 就靠这一条拿到 $67$（买来的 $y = 0$，最多只能自己单干）。
- **两个口径的阈值差 1**：用上买来的那个时，自家粒子要 $y \ge s$（因为集合大小是 $s + 1$）；不用它时，自家粒子只要 $y \ge s - 1$。写反了样例就过不去。
- 「取不满 $s$ 个」的档**不是 $0$，而是不可行**：代码用 `NEG` 哨兵区分，直接当 $0$ 参与比较会凭空造出「选不满也拿分」的错误答案。
- 收益最大到 $2 \times 10^5 \times 10^9 = 2 \times 10^{14}$，必须用 `long long`。
- 商店粒子的 $s$ 上限要同时卡 $y$ 和 $n$，只卡一个会在样例第 2、3 组上错。
- 每组测试点要把两张表和堆清空重建，别把上一组的粒子混进来。

