    价位  :    0   0   0   0   1   0
    是好友:    Y   .   .   Y   Y   .
    好友关系：1-3  1-5  1-6  2-5  2-6  3-4  3-5  5-6
    猫猫 = 3    发瓜人 = 4 6

    价位 0：激活 [1, 2, 3, 4, 6]（去掉猫猫 3）
        发瓜人 4 的连通块 = [4]  ->  中招好友 [4]
        发瓜人 6 的连通块 = [1, 2, 6]  ->  中招好友 [1]
    价位 1：激活 [1, 2, 3, 4, 5, 6]，这一步没有发瓜人
    好友里中招的 = [1, 4]
    答案 = 2

  官方样例 2
    用户  :    1   2   3   4   5   6
    价位  :    0   0   0   0   0   0
    是好友:    Y   .   .   Y   Y   .
    好友关系：1-3  1-5  1-6  2-5  2-6  3-4  3-5  5-6
    猫猫 = 3    发瓜人 = 4

    价位 0：激活 [1, 2, 3, 4, 5, 6]（去掉猫猫 3）
        发瓜人 4 的连通块 = [4]  ->  中招好友 [4]
    好友里中招的 = [4]
    答案 = 1

  结论：样例 1 要屏蔽 2 个好友、样例 2 要屏蔽 1 个，与官方输出 2 / 1 一致。
```

### 思路

1. **传播模型。** 发送者 $s$ 的瓜条金额固定为 $a_s$，只有 $a_v \le a_s$ 的用户才转发它。所以这条瓜条能到达的点集 $=$ 原图在 $\{v: a_v \le a_s\}$ 上 $s$ 所在的连通块。
2. **猫猫从不转发。** 猫猫心动价位是 $0$，一旦拿到瓜条就已经输了（也就会转发）。合法的方案要求他一条都拿不到，所以在传播过程里他永远不转发——等价于**把猫猫这个点从传播图里删掉**。任何「必须经过猫猫才能到达某好友」的路径，都说明猫猫已经拿到了瓜条，那套方案不合法。
3. **答案。** 屏蔽好友只影响「猫猫看不看这个好友的空间」，不影响传播本身。于是答案 $=$ 删掉猫猫后，「能拿到至少一条瓜条的好友」的个数，也就是所有发送者所在连通块与「猫猫好友集合」的并集大小。
4. **算法。** 点按 $a$ 排序、发送者按 $a$ 排序，从小到大逐价位处理：先把该价位的点全部激活（与已激活邻居在 DSU 里合并，**猫猫跳过不激活**），再对该价位的每个发送者，把它所在连通块里「还没计过数的好友」一次性计入答案并清空。为了让「清空」是摊还高效的，给每个 DSU 根挂一份未计数好友的清单，合并时按清单长度小并大，这样每个好友最多被搬运 $O(\log N)$ 次。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

// 并查集：每个连通块额外维护一份「还没被统计过的猫猫好友」清单。
// 合并时把短清单并进长清单（启发式），摊还 O(n log n)。
struct DSU {
    vector<int> p, sz;
    vector<vector<int>> pend;        // pend[root] = 本块内尚未计入答案的好友编号
    vector<char> counted;            // counted[u] = 好友 u 是否已经计入答案

    explicit DSU(int n) : p(n + 1), sz(n + 1, 1), pend(n + 1), counted(n + 1, 0) {
        for (int i = 1; i <= n; i++) p[i] = i;
    }
    int find(int x) {
        while (p[x] != x) { p[x] = p[p[x]]; x = p[x]; }
        return x;
    }
    void unite(int x, int y) {
        int rx = find(x), ry = find(y);
        if (rx == ry) return;
        if (sz[rx] < sz[ry]) swap(rx, ry);
        p[ry] = rx;
        sz[rx] += sz[ry];
        // 清单按长度合并（小并大），保证每个元素被搬运 O(log n) 次
        if (pend[rx].size() < pend[ry].size()) swap(pend[rx], pend[ry]);
        pend[rx].insert(pend[rx].end(), pend[ry].begin(), pend[ry].end());
        pend[ry].clear();
    }
    // 把这个块里所有还没统计的好友一次性计入答案
    int drain(int root, int &ans) {
        if (pend[root].empty()) return 0;
        int add = 0;
        for (int f : pend[root])
            if (!counted[f]) { counted[f] = 1; add++; }
        ans += add;
        pend[root].clear();
        return add;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, e, m, A;
    cin >> n >> e >> m >> A;

    vector<long long> a(n + 1);
    for (int i = 1; i <= n; i++) cin >> a[i];

    vector<vector<int>> adj(n + 1);
    for (int i = 0; i < e; i++) {
        int u, v;
        cin >> u >> v;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    vector<int> senders(m);
    for (int i = 0; i < m; i++) cin >> senders[i];

    DSU dsu(n);
    for (int f : adj[A]) dsu.pend[f].push_back(f);   // 猫猫的每个好友先挂在自己块里

    // 按心动价位从小到大「激活」节点：价位 <= w 的点全部激活后，
    // 每个连通块 = 原图在 {a <= w} 上的连通块。
    vector<int> order(n);
    for (int i = 0; i < n; i++) order[i] = i + 1;
    sort(order.begin(), order.end(), [&](int x, int y) {
        if (a[x] != a[y]) return a[x] < a[y];
        return x < y;
    });
    // 瓜条发送者也按价位排好，便于同一价位一起处理
    sort(senders.begin(), senders.end(), [&](int x, int y) {
        if (a[x] != a[y]) return a[x] < a[y];
        return x < y;
    });

    vector<char> active(n + 1, 0);
    int ans = 0;
    int si = 0;
    for (int i = 0; i < n; ) {
        long long w = a[order[i]];
        int j = i;
        while (j < n && a[order[j]] == w) j++;
        for (int k = i; k < j; k++) {                  // 激活本价位全部节点
            int v = order[k];
            if (v == A) continue;   // 猫猫自己从不转发（他一旦看到就已经输了），传播到他就断了
            active[v] = 1;
            for (int u : adj[v])
                if (active[u]) dsu.unite(v, u);
        }
        while (si < m && a[senders[si]] == w) {         // 价位等于 w 的发送者
            dsu.drain(dsu.find(senders[si]), ans);
            si++;
        }
        i = j;
    }

    cout << ans << "\n";
    return 0;
}
```

### 复杂度

时间 $O((N+E)\alpha(N) + (N+M)\log N)$：排序 $O((N+M)\log N)$，并查集部分接近线性，好友清单的小并大合并摊还 $O(N\log N)$。空间 $O(N+E)$。

### 易错点

- **一定要把猫猫从传播图里删掉**，这是本题最容易错的一步。样例 2 就是专门打这个点的：不删猫猫会得到 $3$，正确答案是 $1$。原因是不删的话「$4$ 的瓜条经猫猫转发给 $1,5$」被算成了中招，而现实中猫猫一旦转发就已经看到瓜条了。
- 一条瓜条被多个发送者带到同一个好友身上只算 $1$ 个，计数要按「好友」去重（代码里用 counted 标记）。
- $a_i$ 到 $10^9$，不能拿来当数组下标；只能排序或离散化后按值分组。
- 好友清单合并若不按长度小并大，菊花图（特殊性质 C）会退化成 $O(N^2)$。

