### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    vector<long long> a(n);
    for (auto &v : a) cin >> v;
    vector<int> eu(m), ev(m);
    vector<vector<int>> g(n);
    for (int i = 0; i < m; i++) {
        cin >> eu[i] >> ev[i];
        --eu[i]; --ev[i];
        g[eu[i]].push_back(ev[i]);
        g[ev[i]].push_back(eu[i]);
    }

    // 源点 s 必须满足 a_s = 0（到自己的最短路是 0）。
    int s = -1;
    for (int i = 0; i < n; i++)
        if (a[i] == 0) { s = i; break; }
    if (s == -1) { cout << -1 << "\n"; return 0; }

    // 从 s 出发，只沿着 a[当前] <= a[下一个] 的边走（值不下降）。
    // 每个点都能这样走到 <=> 存在实数边权使 dist(s,i) = a_i（见题解「从零讲」）。
    vector<char> vis(n, 0);
    vector<int> q;
    q.push_back(s);
    vis[s] = 1;
    for (size_t h = 0; h < q.size(); h++) {
        int x = q[h];
        for (int y : g[x])
            if (!vis[y] && a[x] <= a[y]) { vis[y] = 1; q.push_back(y); }
    }
    for (int i = 0; i < n; i++)
        if (!vis[i]) { cout << -1 << "\n"; return 0; }

    // 边权直接取 |a_u - a_v|：它已经是任何合法方案里这条边的下界。
    for (int i = 0; i < m; i++)
        cout << llabs(a[eu[i]] - a[ev[i]]) << "\n";
    return 0;
}
```

### 复杂度

时间 $O(n + m)$（BFS 每条边看一次），空间 $O(n + m)$。

### 易错点

- 直接给每条边填 $|a_u - a_v|$ 而不判可达性：$a = (0,5,0)$ 的链会漏判，实际无解。
- 不找 $a_i = 0$ 的点，直接从 1 号点出发：$a_1$ 未必是 0。
- 图可能有重边，读入时别去重；输出必须按输入顺序逐条给，重边各占一行。
- 无解时只输出一行 -1，不是 $m$ 行。

