### 参考代码

```cpp
// F. Kaky 的缤纷路径
// 记 T = {v : v 的所有出边都是桥}（即 v 不在任何环上）。
// 结论：存在合法染色 ⟺ T 是独立集（不存在两端都在 T 里的边）。
//   必要性：若某条边的两个端点 u,v 都不在任何环上，从 u 走到 v 的迹只可能原样走这条边
//           （一条两边都是桥的边只能被穿越一次，且 u 侧/ v 侧都没有回路可绕），
//           于是这条迹最多两个点，凑不出三种颜色。
//   充分性：T 是独立集时，把每个 2-边连通块里的一个环上三个连续点染成 R,G,B、
//           块内其余点染 R、T 里的点染 R，可以验证每对点之间都有缤纷路径（本题只判存在性）。
// 实现：Tarjan 求桥（迭代版，防 n=2e5 的链炸栈），再扫一遍所有边。
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;
    while (T--) {
        int n, m;
        cin >> n >> m;
        vector<int> eu(m), ev(m);
        vector<vector<pair<int, int>>> adj(n + 1);
        for (int i = 0; i < m; ++i) {
            int u, v;
            cin >> u >> v;
            eu[i] = u;
            ev[i] = v;
            adj[u].push_back({v, i});
            adj[v].push_back({u, i});
        }

        // ---- 迭代版 Tarjan 求桥 ----
        vector<int> disc(n + 1, 0), low(n + 1, 0), pe(n + 1, -1), it(n + 1, 0);
        vector<char> isBridge(m, 0);
        int timer = 0;
        vector<int> st;
        for (int s = 1; s <= n; ++s) {
            if (disc[s]) continue;
            disc[s] = low[s] = ++timer;
            pe[s] = -1;
            it[s] = 0;
            st.push_back(s);
            while (!st.empty()) {
                int v = st.back();
                if (it[v] < (int)adj[v].size()) {
                    int u = adj[v][it[v]].first, id = adj[v][it[v]].second;
                    ++it[v];
                    if (id == pe[v]) continue;          // 不原路返回
                    if (disc[u]) {
                        low[v] = min(low[v], disc[u]);  // 回边
                    } else {
                        disc[u] = low[u] = ++timer;
                        pe[u] = id;
                        it[u] = 0;
                        st.push_back(u);
                    }
                } else {
                    st.pop_back();
                    if (!st.empty()) {
                        int p = st.back();
                        low[p] = min(low[p], low[v]);
                        if (low[v] > disc[p]) isBridge[pe[v]] = 1;   // 树边是桥
                    }
                }
            }
        }

        // ---- 判定：每条边至少有一个端点「挨过非桥边」 ----
        vector<char> good(n + 1, 0);
        for (int i = 0; i < m; ++i)
            if (!isBridge[i]) {
                good[eu[i]] = 1;
                good[ev[i]] = 1;
            }
        bool ok = true;
        for (int i = 0; i < m; ++i)
            if (!good[eu[i]] && !good[ev[i]]) {
                ok = false;
                break;
            }
        cout << (ok ? "Yes" : "No") << "\n";
    }
    return 0;
}
```

### 复杂度

每组时间 $O(n + m)$、空间 $O(n + m)$；$\sum n \le 2 \times 10^5$、$\sum m \le 3 \times 10^5$。

### 易错点

- $n$ 到 $2 \times 10^5$，一条长链会让递归 DFS 爆栈 —— 求桥要写**迭代版**（用显式栈 + `it[v]` 当前弧指针），实测链状图能稳稳跑过。
- 判定写成「每条边至少有一个端点挨过非桥边」，等价于「$T$ 是独立集」；别写成「每个点都挨过非桥边」（那只对单点成立，容易把第 4 组这种「块之间用桥相连」的图判错）。
- 多组数据要清空 disc / low / isBridge 等数组，$m$ 条边的编号用 0 起更省事。
- 树（$m = n - 1$）全是桥，一定输出 No，可以拿它当自测。

