```cpp
/* D. Canines Canines Paws Claws —— 洛谷 P17180
 *
 * 一、把修改翻译成差分翻转
 *   记 d_i = A_i - A_{i-1} ∈ {+1,-1}。一次「fnrry 修改」枚举 i∈[l,r]：
 *   对每个 i，若 d_i = -1 就把后缀 [i,n] 全体 +2，于是 d_i 从 -1 变成 +1；
 *   若 d_i = +1 就全体 -2，d_i 从 +1 变成 -1。两种情形都是「把 d_i 取反」，
 *   而右侧 d 不受影响，所以整次修改 = 把 d_l..d_r 整体取反。
 *   又因为 l>1，A_1 永远是 1，于是 A_i = i - 2*(d_2..d_i 里 -1 的个数)。
 *
 * 二、把询问翻译成矩阵乘积（k=1 是唯一有戏的档）
 *   记 δ_i = A_{i+1} - A_i = d_{i+1}，取 s_i∈{+1,-1} 表示 B_i = A_i + s_i·k。
 *   |B_{i+1}-B_i| = 1 且 δ_i = ±1，可得 s_{i+1} ≠ s_i 时要求 k=1 且方向受限：
 *   A 上升（δ=+1）时只允许 + → -，A 下降（δ=-1）时只允许 - → +。
 *   · k = 0：B 只能是 A 本身，答案 1；
 *   · k ≥ 2：s 全程不能变号，只有 A+k 与 A-k 两条，答案 2；
 *   · k = 1：答案 = 矩阵乘积 M_l·M_{l+1}…M_{r-1} 的四项之和，其中
 *       δ_i = +1 → M_i = [[1,1],[0,1]] = U，δ_i = -1 → M_i = [[1,0],[1,1]] = L。
 *     于是每次修改就是「把下标 [l-1, r-1] 上的 M 全部换成转置」，询问是区间乘积。
 *
 * 三、在线 + n≤1e12 ⇒ 平衡树
 *   序列由「同值的段」组成，段数 O(m)。用无旋 treap 按位置维护这些段，每段记长度与类型
 *   （U 还是 L）。节点同时存两份乘积：P = 段内矩阵按序相乘，Q = 段内矩阵的转置按序相乘。
 *   整段取反（转置）时恰好 P 与 Q 互换、类型取反，于是一段区间翻转就是一次懒标记；
 *   区间乘积 = 切出中段读 P。段内同类矩阵的幂是 [[1,len],[0,1]] 或其转置，O(1) 算出。
 *
 * 复杂度 O(m log m)。输入量不大但坐标到 1e12，用 fread 快读、全程 stdio。
 */
#include <cstdio>
#include <cstdint>

static const int MOD = 19990721;
static const int MAXNODE = 500005;

struct Mat { int v[4]; };

static inline Mat mul(const Mat &A, const Mat &B) {
    Mat C;
    C.v[0] = (int)(((long long)A.v[0] * B.v[0] + (long long)A.v[1] * B.v[2]) % MOD);
    C.v[1] = (int)(((long long)A.v[0] * B.v[1] + (long long)A.v[1] * B.v[3]) % MOD);
    C.v[2] = (int)(((long long)A.v[2] * B.v[0] + (long long)A.v[3] * B.v[2]) % MOD);
    C.v[3] = (int)(((long long)A.v[2] * B.v[1] + (long long)A.v[3] * B.v[3]) % MOD);
    return C;
}

struct Node {
    int lc, rc;
    long long len, tot;          // 本段长度、子树覆盖的总长度
    uint32_t prio;
    unsigned char type;          // 0: 本段全是 U，1: 本段全是 L
    unsigned char lazy;          // 整棵子树待取反
    Mat P, Q;                    // 子树矩阵按序乘积 / 各自转置后按序乘积
};

static Node tr[MAXNODE];
static int cnt = 0;
static uint32_t rngstate = 0x9e3779b9u;

static inline uint32_t rnd() {
    rngstate ^= rngstate << 13;
    rngstate ^= rngstate >> 17;
    rngstate ^= rngstate << 5;
    return rngstate;
}

/* 本段自己的矩阵 S 与它的转置（同类矩阵的 len 次幂） */
static inline void selfMat(int id, Mat &S, Mat &T) {
    int L = (int)(tr[id].len % MOD);
    if (tr[id].type == 0) {                      // U^len = [[1,len],[0,1]]
        S.v[0] = 1; S.v[1] = L; S.v[2] = 0; S.v[3] = 1;
        T.v[0] = 1; T.v[1] = 0; T.v[2] = L; T.v[3] = 1;
    } else {                                     // L^len = [[1,0],[len,1]]
        S.v[0] = 1; S.v[1] = 0; S.v[2] = L; S.v[3] = 1;
        T.v[0] = 1; T.v[1] = L; T.v[2] = 0; T.v[3] = 1;
    }
}

static inline void pull(int id) {
    int l = tr[id].lc, r = tr[id].rc;
    tr[id].tot = tr[id].len + (l ? tr[l].tot : 0) + (r ? tr[r].tot : 0);
    Mat S, T;
    selfMat(id, S, T);
    if (l) S = mul(tr[l].P, S);
    if (r) S = mul(S, tr[r].P);
    if (l) T = mul(tr[l].Q, T);
    if (r) T = mul(T, tr[r].Q);
    tr[id].P = S;
    tr[id].Q = T;
}

static inline void applyFlip(int id) {
    if (!id) return;
    Mat t = tr[id].P; tr[id].P = tr[id].Q; tr[id].Q = t;
    tr[id].type ^= 1;
    tr[id].lazy ^= 1;
}

static inline void push(int id) {
    if (tr[id].lazy) {
        applyFlip(tr[id].lc);
        applyFlip(tr[id].rc);
        tr[id].lazy = 0;
    }
}

static int newNode(long long len, int type) {
    int id = ++cnt;
    tr[id].lc = tr[id].rc = 0;
    tr[id].len = tr[id].tot = len;
    tr[id].prio = rnd();
    tr[id].type = (unsigned char)type;
    tr[id].lazy = 0;
    Mat S, T;
    selfMat(id, S, T);
    tr[id].P = S;
    tr[id].Q = T;
    return id;
}

/* 前 k 个位置切给 a，其余给 b */
static void split(int t, long long k, int &a, int &b) {
    if (!t) { a = b = 0; return; }
    push(t);
    long long lsz = tr[t].lc ? tr[tr[t].lc].tot : 0;
    if (k <= lsz) {
        split(tr[t].lc, k, a, tr[t].lc);
        b = t;
        pull(b);
    } else if (k >= lsz + tr[t].len) {
        split(tr[t].rc, k - lsz - tr[t].len, tr[t].rc, b);
        a = t;
        pull(a);
    } else {
        long long leftLen = k - lsz;             // 落在本段中间，拆成两段
        int nr = newNode(tr[t].len - leftLen, tr[t].type);
        tr[nr].rc = tr[t].rc;
        tr[t].rc = 0;
        tr[t].len = leftLen;
        pull(t);
        pull(nr);
        a = t;
        b = nr;
    }
}

static int merge(int a, int b) {
    if (!a) return b;
    if (!b) return a;
    if (tr[a].prio < tr[b].prio) {
        push(a);
        tr[a].rc = merge(tr[a].rc, b);
        pull(a);
        return a;
    }
    push(b);
    tr[b].lc = merge(a, tr[b].lc);
    pull(b);
    return b;
}

namespace fastio {
const int BUFSZ = 1 << 20;
char buf[BUFSZ];
char *p1 = buf, *p2 = buf;
inline char gc() {
    if (p1 == p2) {
        p2 = (p1 = buf) + fread(buf, 1, BUFSZ, stdin);
        if (p1 == p2) return 0;
    }
    return *p1++;
}
inline long long rd() {
    char c = gc();
    while (c < '0' || c > '9') {
        if (!c) return 0;
        c = gc();
    }
    long long r = 0;
    while (c >= '0' && c <= '9') {
        r = r * 10 + (c - '0');
        c = gc();
    }
    return r;
}
}  // namespace fastio

int main() {
    long long n = fastio::rd();
    int m = (int)fastio::rd();
    int root = (n >= 2) ? newNode(n - 1, 0) : 0;   // 初始 d 全为 +1 ⇒ 全是 U
    long long lastans = 0;
    for (int q = 0; q < m; ++q) {
        int o = (int)fastio::rd();
        if (o == 0) {
            long long lp = fastio::rd(), rp = fastio::rd();
            long long l = (lp + lastans) % n + 2;
            long long r = (rp + lastans) % n + 2;
            int a, b, c;
            split(root, l - 2, a, b);              // 切出下标 [l-1, r-1]
            split(b, r - l + 1, b, c);
            applyFlip(b);
            root = merge(a, merge(b, c));
        } else {
            long long lp = fastio::rd(), rp = fastio::rd(), k = fastio::rd();
            long long l = (lp + lastans) % n + 1;
            long long r = (rp + lastans) % n + 1;
            int ans;
            if (k == 0) {
                ans = 1;
            } else if (k >= 2) {
                ans = 2;
            } else if (l == r) {
                ans = 2;                            // 空乘积 = 单位矩阵，四项和 = 2
            } else {
                int a, b, c;
                split(root, l - 1, a, b);           // 下标 [l, r-1] 上的矩阵乘积
                split(b, r - l, b, c);
                const Mat &M = tr[b].P;
                long long s = (long long)M.v[0] + M.v[1] + M.v[2] + M.v[3];
                ans = (int)(s % MOD);
                root = merge(a, merge(b, c));
            }
            printf("%d\n", ans);
            lastans = ans;
        }
    }
    return 0;
}
```

### 易错点

- 修改的正确翻译是「$d_l..d_r$ 全部取反」，不是「把 $A$ 的某一段整体 $\pm2$」。推不出这一步就只能写 $O(n)$ 模拟，$n=10^{12}$ 直接爆。
- 下标要**平移一位**：$M_i$ 依赖 $\delta_i=A_{i+1}-A_i=d_{i+1}$，所以修改 $[l,r]$ 作用在矩阵下标 $[l-1,r-1]$，询问 $[l,r]$ 要的是矩阵下标 $[l,r-1]$。写成 $[l,r]$ 会全盘错位。
- 三类 $k$ 别混：$k=0$ 是 1、$k\ge2$ 恒为 2，只有 $k=1$ 才走矩阵；$k=1$ 且 $l=r$ 时乘积为空（四项和 2），别去读空节点的矩阵（那样会读到 0）。
- $lastans$ 用的是**取模之后**的输出值，而且必须真在线：不能把询问攒起来离散化，段的位置只能靠平衡树动态维护。
- 答案要模 $19990721$，但段长 $len$ 本身要开 `long long`（可到 $10^{12}$），只在算矩阵幂时对模数取余。
- 转置懒标记要**同时**交换 $P,Q$ 并翻转类型：只换 $P$ 的话，标记下推后子节点的段内矩阵还是旧的，乘积就错了。
- 建树时别忘了 $n\ge2$ 才有矩阵下标：$n=1$ 时矩阵序列为空，任何查询都走「空乘积」分支。

